@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Cinzel:wght@400;500;600;700&display=swap');
:root{--ink:#08090e;--wine:#861f34;--red:#c13a4e;--cream:#e9dfd2;--muted:#989196;--gold:#bd9d71;--line:rgba(222,206,190,.16);font-family:'DM Sans',sans-serif;color:var(--cream);font-synthesis:none}*{box-sizing:border-box}html,body,#game-root{width:100%;height:100%;margin:0;overflow:hidden;background:var(--ink)}body{overscroll-behavior:none}#game-root{position:relative;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:-2;outline:0}.vignette{position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(90deg,rgba(8,9,14,.91) 0%,rgba(8,9,14,.77) 28%,rgba(8,9,14,.25) 60%,rgba(8,9,14,.22) 100%),linear-gradient(0deg,rgba(4,5,9,.68),transparent 30%,rgba(4,5,9,.22));box-shadow:inset 0 0 200px 55px rgba(0,0,0,.52)}.topbar{position:absolute;top:0;left:0;right:0;height:82px;padding:0 4.7vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(220,204,190,.1);background:linear-gradient(180deg,rgba(7,8,12,.77),transparent);z-index:5}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:var(--cream)}.brand-mark{font:600 26px 'Cinzel',serif;color:#d4ad7e;border:1px solid rgba(198,166,124,.5);width:38px;height:38px;text-align:center;line-height:38px;transform:rotate(45deg);font-size:23px}.brand-mark:first-letter{transform:rotate(-45deg)}.brand-copy{display:grid;gap:4px;letter-spacing:2px}.brand-copy b{font:600 12px 'Cinzel',serif;letter-spacing:2.6px}.brand-copy small{color:#948a87;font-size:8px;letter-spacing:3.1px}.top-right{display:flex;align-items:center;gap:13px}.server-pill{font-size:9px;letter-spacing:1.6px;color:#aca3a0;padding:10px 12px;border:1px solid var(--line);background:rgba(16,16,20,.36)}.server-pill i,.pulse-dot,.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a93445;box-shadow:0 0 12px #c33249;margin-right:8px}.icon-btn{width:34px;height:34px;border:1px solid var(--line);background:rgba(20,19,23,.5);color:#c6b7aa;font-size:15px;cursor:pointer}.icon-btn:hover,.clan-switch:hover{border-color:var(--gold);color:var(--gold)}.screen{position:absolute;inset:0;z-index:2}.hidden{display:none!important}.lobby-copy{position:absolute;top:16.5%;left:10.1%;width:min(450px,44vw);animation:fadein 1.1s ease both}.eyebrow{font-size:9px;letter-spacing:2.3px;color:#c5a47d;font-weight:600;margin:0 0 21px}.eyebrow span{display:inline-block;width:21px;border-top:1px solid #9c3d4c;vertical-align:middle;margin-right:9px}.lobby h1,.result h2{font:500 clamp(43px,5.7vw,76px)/.98 'Cinzel',serif;letter-spacing:2px;color:#eee5dc;margin:0 0 18px;text-shadow:0 8px 40px #000}.lobby h1 em,.result h2 em{font-style:normal;color:#a52d40}.intro{font-size:12px;color:#b1a9a7;line-height:1.75;letter-spacing:.1px;margin:0 0 24px}.clan-row{width:336px;height:58px;display:flex;align-items:center;border-top:1px solid var(--line);border-bottom:1px solid var(--line);gap:12px}.clan-seal{width:34px;height:34px;border:1px solid #805640;color:#c1a17c;text-align:center;line-height:32px;font-size:18px}.clan-row>div:nth-child(2){display:grid;gap:3px}.clan-row small,.mode-label,.mode-card small{color:#938b89;font-size:8px;letter-spacing:1.35px}.clan-row strong{font:600 12px 'Cinzel',serif;letter-spacing:1.35px}.clan-row strong span{color:#c99d6b;font-size:11px}.clan-rule{flex:1}.clan-switch{width:25px;height:25px;border:1px solid var(--line);background:transparent;color:#aaa;cursor:pointer}.mode-label{margin:22px 0 9px;display:flex;justify-content:space-between;width:340px;color:#c4b8af;font-size:9px;letter-spacing:1.7px}.mode-label span{color:#837979}.mode-selector{width:350px;display:flex;gap:7px}.mode-card{flex:1;min-width:0;height:62px;background:rgba(17,17,21,.7);border:1px solid rgba(220,204,190,.15);color:#ddd3ca;text-align:left;display:flex;align-items:center;gap:7px;padding:0 8px;position:relative;cursor:pointer;transition:.2s}.mode-card.active{background:rgba(89,25,36,.48);border-color:#873846}.mode-card:hover{border-color:#bd815e}.mode-icon{font-size:16px;color:#b69371}.mode-card span:nth-child(2){display:grid;gap:5px}.mode-card b{font:600 9px 'Cinzel',serif;letter-spacing:1px}.mode-card small{font-size:7px;letter-spacing:.1px;white-space:nowrap}.mode-card>i{position:absolute;right:6px;top:6px;font-style:normal;font-size:9px;color:#d2a16e}.play-button{margin-top:14px;width:350px;height:49px;display:flex;justify-content:space-between;align-items:center;padding:0 18px;background:linear-gradient(105deg,#7f2335,#a72e42 55%,#7c1d31);border:1px solid #c1505b;color:#f2e7dc;letter-spacing:2px;font:600 10px 'Cinzel',serif;cursor:pointer;box-shadow:0 8px 30px rgba(92,19,33,.3);transition:.2s}.play-button b{font:400 20px 'DM Sans';transition:transform .2s}.play-button:hover{filter:brightness(1.2);box-shadow:0 8px 36px rgba(175,40,58,.38)}.play-button:hover b{transform:translateX(4px)}.queue-note{width:350px;margin-top:12px;color:#8f8987;text-align:center;font-size:9px;letter-spacing:.45px}.queue-note b{color:#d2c4b8}.pulse-dot{width:5px;height:5px;margin-right:5px;animation:pulse 1.5s infinite}.lobby-bottom{position:absolute;bottom:25px;left:4.7%;right:4.7%;display:flex;justify-content:space-between;color:#847c7c;font-size:8px;letter-spacing:1.5px;border-top:1px solid rgba(220,204,190,.1);padding-top:13px}.loading{position:absolute;inset:0;z-index:10;background:#090a10;display:flex;align-items:center;justify-content:center;flex-direction:column;transition:opacity .5s}.loading.done{opacity:0;pointer-events:none}.loader-mark{font:500 50px 'Cinzel';color:#cba77b;animation:glow 1.5s infinite}.loading p{font-size:9px;letter-spacing:3px;color:#a39b99}.settings-modal{position:absolute;inset:0;background:rgba(4,5,8,.75);z-index:9;display:grid;place-items:center;backdrop-filter:blur(8px)}.settings-panel{position:relative;background:#14141a;border:1px solid #62414a;padding:34px;width:min(410px,90vw);box-shadow:0 30px 90px #000}.settings-panel h2{font:500 30px 'Cinzel';margin:0 0 26px}.settings-panel label{display:grid;gap:10px;margin:18px 0;font-size:9px;letter-spacing:1.3px;color:#b5aaa5}.settings-panel select{background:#202027;color:#eee;border:1px solid #504147;padding:11px;font:12px 'DM Sans'}.settings-panel input[type=range]{accent-color:#a53548}.settings-panel .toggle-line{display:flex;justify-content:space-between;align-items:center}.settings-panel input[type=checkbox]{accent-color:#a53548}.modal-close{position:absolute;right:14px;top:12px;background:none;border:0;color:#ddd;font-size:24px;cursor:pointer}.settings-note{font-size:10px;color:#82797b;line-height:1.6;margin-top:22px}.hud{pointer-events:none}.hud button,.hud .joystick{pointer-events:auto}.match-top{position:absolute;top:22px;left:25px;right:25px;display:flex;align-items:center;gap:22px}.match-title{display:grid;grid-template-columns:9px auto;align-items:center;column-gap:5px}.match-title .live-dot{grid-row:span 2;margin:0;width:6px;height:6px}.match-title b{font:600 10px 'Cinzel';letter-spacing:1.3px}.match-title small{font-size:8px;color:#b6a9a3;letter-spacing:1.2px;margin-top:4px}.match-stats{display:flex;gap:18px;margin-left:auto;align-items:center;background:rgba(8,9,13,.58);border:1px solid rgba(230,220,210,.16);padding:9px 16px}.match-stats div:not(.stat-divider){display:grid;gap:3px;text-align:center}.match-stats small{font-size:7px;letter-spacing:1.2px;color:#c5b9b1}.match-stats b{font:500 17px 'Cinzel';color:#eee}.stat-divider{width:1px;height:24px;background:var(--line)}.leave-btn{border:1px solid var(--line);background:rgba(8,9,13,.62);color:#e2d9d2;padding:8px 10px;font-size:12px}.leave-btn span{font-size:8px;letter-spacing:1px}.compass{position:absolute;top:83px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;color:#ddd;font:11px 'Cinzel';text-shadow:0 2px 6px #000}.compass span{font-size:8px;color:#c7bbb4}.compass i{width:25px;border-top:1px solid #ddd7}.compass b{font-size:15px;color:#f0d7b8}.crosshair{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:15px;height:15px}.crosshair i{position:absolute;background:rgba(255,235,215,.82);box-shadow:0 0 4px #000}.crosshair i:first-child{width:1px;height:13px;left:7px;top:1px}.crosshair i:last-child{height:1px;width:13px;top:7px;left:1px}.bottom-left{position:absolute;left:28px;bottom:26px;width:250px}.player-chip{display:flex;align-items:center;gap:10px;margin-bottom:12px}.avatar{width:34px;height:34px;border:1px solid #bd7f65;background:linear-gradient(140deg,#49212c,#1b1b20);display:grid;place-items:center;font:17px 'Cinzel';color:#dabd9a}.player-chip div:nth-child(2){display:grid;gap:4px}.player-chip b{font:600 9px 'Cinzel';letter-spacing:1.15px}.player-chip small{color:#b4a9a5;font-size:7px;letter-spacing:1px}.mic{margin-left:auto;color:#c5b5a9}.vitals{display:grid;gap:6px}.vital-row{display:flex;align-items:center;gap:8px;height:11px}.vital-row>span{width:11px;font-size:10px;color:#cb4551}.vital-row>b{font-size:9px;width:24px;text-align:right;color:#e3d8d1}.meter{height:4px;background:rgba(240,230,220,.25);flex:1;max-width:180px}.meter i{height:100%;display:block;background:#b83245;transition:width .2s}.meter .blood-fill{background:#b08c65}.meter .armor-fill{background:#788aa0}.blood-row>span{color:#bb8f68}.armor-row>span{color:#93a6b8}.weapon-card{position:absolute;bottom:25px;left:50%;transform:translateX(-50%);width:213px;height:61px;background:rgba(10,11,15,.74);border:1px solid rgba(224,205,186,.25);display:flex;align-items:center;padding:9px 12px;gap:12px}.weapon-icon{font-size:25px;color:#d0aa7c;transform:rotate(-35deg)}.weapon-info{display:grid;gap:4px}.weapon-info small{font-size:7px;color:#b39d8b;letter-spacing:1px}.weapon-info b{font:600 10px 'Cinzel';letter-spacing:.8px}.weapon-info b span{font-size:8px;color:#c39b71}.weapon-info .ammo{font-size:8px;color:#d9cec4}.weapon-info .ammo strong{font-size:12px;color:#fff}.weapon-info .ammo i{font-style:normal;color:#756e6b;margin:0 4px}.weapon-key{margin-left:auto;align-self:flex-start;border:1px solid #64544d;padding:2px 5px;color:#ddd;font-size:8px}.right-controls{position:absolute;right:27px;bottom:32px;display:flex;gap:11px;align-items:end}.ability-button{position:relative;width:65px;height:65px;border:1px solid rgba(211,171,127,.56);background:radial-gradient(circle at center,rgba(121,52,61,.64),rgba(17,15,20,.88));color:#d9b786;display:grid;place-items:center;align-content:center;gap:4px;cursor:pointer;overflow:hidden}.ability-button span{font-size:21px}.ability-button small{font-size:6px;letter-spacing:.5px;color:#e6d9cd}.ability-button kbd{position:absolute;top:4px;right:5px;background:#282127;color:#cdb898;border:1px solid #624d4b;font-size:7px;padding:1px 3px}.ability-button .cooldown{position:absolute;inset:0;background:rgba(6,7,10,.7);transform:translateY(100%);transition:transform .15s}.feed-button{border-color:rgba(184,75,84,.58);background:radial-gradient(circle,rgba(104,27,42,.65),rgba(17,15,20,.9))}.toast{position:absolute;left:50%;top:68%;transform:translate(-50%,-50%);background:rgba(9,9,13,.86);border:1px solid #8a414d;padding:12px 20px;color:#e3c9b0;font:10px 'Cinzel';letter-spacing:1.4px;opacity:0;transition:.3s}.toast.show{opacity:1}.zone-warning{position:absolute;top:25%;left:50%;transform:translateX(-50%);font:600 11px 'Cinzel';letter-spacing:2px;color:#e88a72;text-shadow:0 0 14px #c22b36;animation:pulse 1.2s infinite}.hint{position:absolute;left:50%;bottom:8px;transform:translateX(-50%);font-size:7px;letter-spacing:1.3px;color:rgba(236,226,217,.56);white-space:nowrap}.hint span{color:#a34850;margin:0 6px}.result{display:grid;place-items:center;background:rgba(5,6,9,.62);backdrop-filter:blur(5px);pointer-events:auto}.result-box{text-align:center;width:min(440px,90vw);padding:35px;background:linear-gradient(145deg,rgba(15,14,20,.94),rgba(27,14,20,.92));border:1px solid rgba(195,119,99,.48);box-shadow:0 20px 100px #000}.result-icon{font-size:27px;color:#bd8b69}.result .eyebrow{margin:12px 0}.result h2{font-size:42px;margin-bottom:14px}.result-box>p:not(.eyebrow){font-size:11px;color:#b9aeaa}.result-stats{display:flex;justify-content:space-around;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:16px 0;margin:20px 0}.result-stats div{display:grid;gap:7px}.result-stats small{font-size:7px;letter-spacing:1px;color:#a89c95}.result-stats b{font:500 17px 'Cinzel'}.result .play-button{width:100%;margin:0}.mobile-controls{display:none}.joystick{position:absolute;left:24px;bottom:34px;width:106px;height:106px;border-radius:50%;background:rgba(15,15,20,.36);border:1px solid rgba(230,218,206,.3);touch-action:none}.stick{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:43px;height:43px;border-radius:50%;background:rgba(207,187,169,.33);border:1px solid rgba(240,218,199,.58);box-shadow:0 3px 16px #000}.touch-actions{position:absolute;right:18px;bottom:22px;display:flex;gap:9px;align-items:end}.touch-act{width:56px;height:56px;border-radius:50%;background:rgba(22,17,21,.7);border:1px solid rgba(230,218,206,.42);color:#eee;font-size:18px;display:grid;place-items:center;align-content:center;gap:1px}.touch-act small{font-size:6px;letter-spacing:.5px}.fire-touch{width:68px;height:68px;border-color:#c64f54;background:rgba(95,25,37,.62)}.ability-touch{color:#d1ac7a}
@keyframes pulse{50%{opacity:.42}}@keyframes glow{50%{text-shadow:0 0 24px #a44a4f}}@keyframes fadein{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@media(max-width:700px){.topbar{height:61px;padding:0 16px}.brand-mark{width:29px;height:29px;line-height:29px;font-size:18px}.brand{gap:9px}.brand-copy b{font-size:9px;letter-spacing:1.6px}.brand-copy small{font-size:6px;letter-spacing:2px}.server-pill{display:none}.top-right{gap:7px}.icon-btn{width:30px;height:30px}.vignette{background:linear-gradient(90deg,rgba(8,9,14,.86),rgba(8,9,14,.34) 70%),linear-gradient(0deg,rgba(4,5,9,.68),transparent 42%,rgba(4,5,9,.28));box-shadow:inset 0 0 100px 20px rgba(0,0,0,.48)}.lobby-copy{left:7%;top:12%;width:86%;}.lobby h1{font-size:clamp(43px,13vw,64px);margin-bottom:13px}.intro{font-size:11px;line-height:1.6;margin-bottom:17px}.clan-row{width:100%;height:51px}.mode-label{width:100%;margin-top:16px}.mode-selector{width:100%;gap:5px}.mode-card{height:57px;padding:0 6px;gap:5px}.mode-card small{font-size:6px}.mode-card b{font-size:8px}.mode-icon{font-size:13px}.mode-card>i{font-size:8px}.play-button,.queue-note{width:100%}.play-button{height:45px;margin-top:11px}.queue-note{margin-top:8px}.lobby-bottom{bottom:11px;left:6%;right:6%;font-size:6px;letter-spacing:.8px;padding-top:9px}.match-top{top:12px;left:12px;right:12px;gap:7px}.match-title b{font-size:8px}.match-title small{font-size:6px}.match-stats{gap:9px;padding:7px 8px}.match-stats small{font-size:6px;letter-spacing:.5px}.match-stats b{font-size:13px}.leave-btn{padding:7px;font-size:10px}.leave-btn span{display:none}.stat-divider{height:19px}.compass{top:61px}.bottom-left{left:14px;bottom:20px;width:185px}.player-chip{gap:7px;margin-bottom:8px}.player-chip b{font-size:8px}.player-chip small{font-size:6px}.avatar{width:29px;height:29px}.meter{max-width:120px}.vital-row{height:10px}.weapon-card{bottom:14px;left:50%;width:150px;height:47px;padding:5px 8px;gap:6px;transform:translateX(-50%)}.weapon-icon{font-size:19px}.weapon-info{gap:2px}.weapon-info small{font-size:5px}.weapon-info b{font-size:8px}.weapon-info .ammo strong{font-size:10px}.weapon-key{font-size:7px}.right-controls{right:13px;bottom:88px;gap:7px}.ability-button{width:49px;height:49px}.ability-button span{font-size:15px}.ability-button small{font-size:5px}.hint{display:none}.mobile-controls{display:block}.joystick{left:18px;bottom:24px;width:98px;height:98px}.touch-actions{right:13px;bottom:17px;gap:6px}.touch-act{width:48px;height:48px;font-size:15px}.fire-touch{width:59px;height:59px}.zone-warning{top:18%;font-size:9px;white-space:nowrap}.toast{top:58%;font-size:8px;white-space:nowrap}.result-box{padding:25px}.result h2{font-size:35px}}
